create table if not exists public.program_member_slot_snapshots(program_id text not null,pole_id uuid not null,member_id text not null,service_date date not null,start_time text,end_time text,updated_at timestamptz not null default now(),primary key(program_id,pole_id,member_id,service_date));
alter table public.program_member_slot_snapshots enable row level security;
create or replace function public.snapshot_program_member_slots_before_delete() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.program_member_slot_snapshots(program_id,pole_id,member_id,service_date,start_time,end_time,updated_at) select pa.program_id,pa.pole_id,old.member_id,pd.service_date,s.start_time,s.end_time,now() from public.program_assignments pa join public.program_assignment_member_slots s on s.assignment_member_id=old.id join public.program_days pd on pd.id=s.program_day_id where pa.id=old.assignment_id on conflict(program_id,pole_id,member_id,service_date) do update set start_time=excluded.start_time,end_time=excluded.end_time,updated_at=now();return old;end $$;
create or replace function public.restore_program_member_slots_after_insert() returns trigger language plpgsql security definer set search_path=public as $$ declare v_program text;v_pole uuid;begin select program_id,pole_id into v_program,v_pole from public.program_assignments where id=new.assignment_id;insert into public.program_assignment_member_slots(assignment_member_id,program_day_id,start_time,end_time) select new.id,pd.id,coalesce(s.start_time,pd.start_time),coalesce(s.end_time,pd.end_time) from public.program_days pd left join public.program_member_slot_snapshots s on s.program_id=v_program and s.pole_id=v_pole and s.member_id=new.member_id and s.service_date=pd.service_date where pd.program_id=v_program and (s.service_date is not null or not exists(select 1 from public.program_member_slot_snapshots sx where sx.program_id=v_program and sx.pole_id=v_pole and sx.member_id=new.member_id)) on conflict(assignment_member_id,program_day_id) do nothing;return new;end $$;
drop trigger if exists trg_snapshot_program_member_slots on public.program_assignment_members;create trigger trg_snapshot_program_member_slots before delete on public.program_assignment_members for each row execute function public.snapshot_program_member_slots_before_delete();
drop trigger if exists trg_restore_program_member_slots on public.program_assignment_members;create trigger trg_restore_program_member_slots after insert on public.program_assignment_members for each row execute function public.restore_program_member_slots_after_insert();